<?php
declare(strict_types=1);
if (getenv('BERSERK_STAGE31_ISOLATED') !== '1' || file_exists(__DIR__.'/../.git')) throw new RuntimeException('Disposable copy required');
$config=require __DIR__.'/../config/db.php';
if($config['host']!=='127.0.0.1:33388'||$config['name']!=='berserk_stage31'||$config['user']!=='stage31')throw new RuntimeException('Wrong test configuration');
require __DIR__.'/stage31_fixtures.php';
use Berserk\Core\{Db,GameRepository,CommandJournalRepository,GameState,Engine,Command,InstantProcessor,StrikeResolver,InformationalWaitManager};
$db=new Db($config);$proof=$db->fetchOne('SELECT @@datadir AS dir,@@port AS port,DATABASE() AS db');
if((int)$proof['port']!==33388||!str_contains(str_replace('\\','/',$proof['dir']),'/stage3-1-verification/data/'))throw new RuntimeException('Wrong DB instance');
$repo=new GameRepository($db);$journal=new CommandJournalRepository($db);$cmdNo=0;
function s31persist(GameState $fixture):GameState{global $repo;$row=$repo->create(101,202);$fixture->gameId=$row->gameId;$fixture->persistenceVersion=$row->persistenceVersion;$fixture->persistenceJson=$row->persistenceJson;$repo->save($fixture);return $repo->findById($fixture->gameId);}
function s31dbcmd(GameState &$s,string $actor,string $type,array $payload=[],?string $id=null):array{global $repo,$journal,$cmdNo;$id??='s31_'.(++$cmdNo).'_'.bin2hex(random_bytes(6));$before=$s->persistenceVersion;$a=$journal->registerProcessing($s->gameId,$actor,$id,$type,$payload,$before);if($a['is_new'])$repo->executeLockedCommand($s,$journal,(int)$a['id'],fn($w)=>(new Engine())->apply($w,$actor,new Command($type,$payload)));$s=$repo->findById($s->gameId);$a=$journal->findById((int)$a['id']);s31trace($s,'DB:'.$type.':'.$a['status']);return ['record'=>$a,'before'=>$before,'id'=>$id,'actor'=>$actor,'type'=>$type,'payload'=>$payload];}
function s31dbok(GameState &$s,string $actor,string $type,array $payload=[]):array{$a=s31dbcmd($s,$actor,$type,$payload);s31check($a['record']['status']==='committed','DB '.$type.' '.$a['record']['error_message']);return $a;}
function s31dbretry(GameState &$s,array $a):void{global $repo,$journal;$v=$s->persistenceVersion;$again=$journal->registerProcessing($s->gameId,$a['actor'],$a['id'],$a['type'],$a['payload'],$a['before']);s31check(!$again['is_new']&&$again['status']==='committed','same command committed');$s=$repo->findById($s->gameId);s31check($s->persistenceVersion===$v,'retry no new save');}
function s31dback(GameState &$s):void{foreach(['host','player']as$p)if($s->status==='battle'&&($s->battle['strike']['state']??'')==='results'&&!in_array($p,$s->battle['strike']['confirmed']??[],true))s31dbok($s,$p,'confirm_strike',['wait_id'=>(string)InformationalWaitManager::token($s)]);}
s31test('DB R1 dice pause resume metadata and final HP',function(){$s=s31state();s31combat($s,3);unset($s->battle['strike']['combat_instant_window']);$s->battle['strike']['instant_stack']=[s31item(3,'host',['type'=>'dice_choice'],'dice'),s31item(90,'host',['type'=>'strike_level','mode'=>'reduce_one'],'value')];(new InstantProcessor($s,new Engine()))->resolveStack();$s=s31persist($s);$a=s31dbok($s,'host','choose_dice_choice',['choice'=>'plus:own']);s31check($s->getCard(2)->hp===18&&count($s->battle['strike']['strike_level_effects'])===1,'metadata saved; weak damage2');s31check($s->battle['strike']['base_result']['attack']==='medium'&&$s->battle['strike']['result']['attack']==='weak'&&$s->battle['strike']['strike_level_effects']===[['side'=>'attack','mode'=>'reduce_one']],'base and resolved transformations persisted exactly');s31dbretry($s,$a);s31dback($s);s31check($s->getCard(2)->hp===18&&empty($s->battle['strike']),'ACK no damage repeat');return ['hp'=>18,'retry'=>'same journal id'];});
s31test('DB R2 cancellation followed by next queued item',function(){$s=s31wounds();$s->battle['strike']['instant_resolution']['queue'][]=s31item(90,'host',['type'=>'redistribute_wounds'],'wounds',1);$s=s31persist($s);$a=s31dbok($s,'host','cancel_pending');s31check(($s->battle['pending_wound_transfer']['source_id']??0)===90,'next source persisted');s31dbretry($s,$a);s31check(($s->battle['pending_wound_transfer']['source_id']??0)===90,'retry does not cancel next item');s31dbok($s,'host','cancel_pending');s31check(empty($s->battle['strike'])&&$s->getCard(1)->hp===18,'combat cleared HP unchanged');return ['hp'=>18,'pending'=>false];});
s31test('DB R2 refund idempotent same command',function(){$s=s31state();$s->getCard(1)->hp=18;$s->getCard(3)->coins=3;s31check((new \Berserk\Core\WoundTransferProcessor($s,new Engine()))->start('host',$s->getCard(3),['coins_cost'=>2])->success,'start');$s=s31persist($s);$a=s31dbok($s,'host','cancel_pending');s31dbretry($s,$a);s31check($s->getCard(3)->coins===3,'single refund');return ['coins'=>3];});
s31test('DB R3 cancel repeat preserves completed application',function(){$s=s31persist(s31valhalla());s31dbok($s,'host','valhalla_pick',['target_id'=>2]);$a=s31dbok($s,'host','cancel_pending');s31dbretry($s,$a);s31check($s->getCard(2)->hp===19&&empty($s->battle['pending_valhalla_pick']),'first remains');s31check(!empty($s->getCard(3)->flags['ragnar_valhalla_double_used_this_turn']),'repeat remains spent');return ['hp'=>19,'repeat_spent'=>true];});
s31test('DB H1 closed persisted before immediate end_turn',function(){s31roll();$s=s31persist(s31state(['attack_series'=>true,'unanswer'=>true]));s31dbok($s,'host','strike',['card_id'=>1,'target_id'=>2]);s31dback($s);$first=json_encode($s->toArray());s31trace($s,'DB:H1:after-battle');$a=s31dbok($s,'host','attack_series_end');s31dbretry($s,$a);s31check($s->getCard(1)->closed,'closed persisted');s31trace($s,'DB:H1:after-series-end');s31dbok($s,'host','end_turn');s31trace($s,'DB:H1:after-end-turn');for($i=0;$i<10&&!empty($s->battle['turn_phase']);$i++){$tp=$s->battle['turn_phase'];s31check(!empty($tp['pending_ack']),'phase ACK expected');s31dbok($s,$tp[$tp['side'].'_key'],'turn_ack');}s31check($s->battle['active']==='player'&&$s->getCard(1)->closed&&$s->getCard(2)->hp===16,'next turn retained closing damage');s31check(!json_decode($first,true)['cards'][1]['closed'],'immutable first unchanged');s31trace($s,'DB:H1:next-player-ready');return ['first_closed'=>false,'end_closed'=>true,'next_closed'=>true,'hp'=>16];});
s31test('DB R2 cancellation before result ACK then automatic ACK',function(){$s=s31wounds();$s->battle['strike']['wounds_after_result_ack']=false;$s->battle['strike']['confirmed']=[];\Berserk\Core\TurnTimer::prepare($s,'host');\Berserk\Core\TurnTimer::resume($s,1,'start_phase',time());$s=s31persist($s);s31dbok($s,'host','cancel_pending');s31check(($s->battle['strike']['state']??'')==='results','returns to results');s31dbok($s,'host','confirm_strike',['wait_id'=>(string)InformationalWaitManager::token($s)]);$wait=InformationalWaitManager::record($s);s31check($wait!==null,'timed ACK available');global $db,$repo;$engine=new Engine(null,fn()=>$wait['deadline_at']);$r=(new \Berserk\Core\InformationalAutoAck($db,$repo,$engine))->checkOutcome($s,'host');$s=$repo->findById($s->gameId);s31check($r->certain&&empty($s->battle['strike'])&&$s->getCard(1)->hp===18,'auto ACK completes without new wounds');s31trace($s,'DB:R2:auto-ACK-complete');return ['hp'=>18,'auto_ack'=>true,'combat_cleared'=>true];});
if($p=getenv('STAGE31_RESULTS'))file_put_contents($p,json_encode(['environment'=>$proof,'results'=>$results,'traces'=>$traces],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
foreach($results as$r)echo $r['status'].' '.$r['case'].' '.json_encode($r['detail']??$r['error'],JSON_UNESCAPED_UNICODE)."\n";
exit(count(array_filter($results,fn($r)=>$r['status']==='FAIL'))?1:0);
